	private static void seed(Path directory, LmdbStoreConfig config, boolean marked) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(S, P, OBJECT);
				connection.add(T, P, LITERAL);
				connection.add(T, Q, LITERAL);
				connection.commit();
				if (marked) {
					connection.begin();
					connection.remove(T, P, LITERAL);
					connection.commit();
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void advance(Path directory, LmdbStoreConfig config) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(U, Q, OBJECT);
				connection.commit();
			}
		} finally {
			repository.shutDown();
		}
	}

